groupResourcesByLoadStrategy([
  { id: "a", tag: "script", duration: 100 },
  { id: "b", tag: "script", async: true, duration: 50 },
  { id: "c", tag: "link", rel: "stylesheet", duration: 30 },
  { id: "d", tag: "link", rel: "preload" },
])
